const TW = { capital: 'In Dhaka, where traffic is heaviest', port: "In the country's second-largest city", tourist: 'On the main tourist strip', terminal: 'Launch passengers walk past it', shopping: 'In a main shopping area', hwtown: 'In a town on the {route} road', sylcover: 'One of {n} Sylhet points. Together they cover most of the city.' };
const gt = () => GT[S.goal] || [];
const tags = b => P.city[b.c][3];
const tagWhy = (t, c) => TW[t].replace('{route}', (P.routes.find(r => r[2].includes(c)) || [0, ''])[1]).replace('{n}', B.filter(b => b.c === c).length);
const pscore = b => {
  if (S.aud === 'near' && S.place && S.place.la != null) { const k = km([S.place.la, S.place.lo], [b.la, b.lo]); return [k <= 2 ? 50 : k <= 5 ? 40 : k <= 10 ? 30 : 0, k]; }
  if (S.aud === 'city' || S.aud === 'multi') return [S.cities.includes(b.c) ? 50 : 0, null];
  if (S.aud === 'route' && S.route) { const r = RT(S.route); return [r[2].includes(b.c) ? 50 : r[3].includes(b.c) ? 35 : 0, null]; }
  return [0, null];
};
const rank = b => { const [p, k] = pscore(b), g = tags(b).some(t => gt().includes(t)); return p + (g ? 30 : 0) + (b.x ? 0 : 5) - (k || 0) * .01; };
