const pl = () => S.place.t === 'me' ? 'your area' : S.place.l;
const placeKnown = () => !!((S.aud === 'near' && S.place) || ((S.aud === 'city' || S.aud === 'multi') && S.cities.length) || (S.aud === 'route' && S.route));
const isCheck = () => !!((S.place && S.place.t === 'q') || (S.aud === 'route' && S.route && !RT(S.route)[2].length) || (placeKnown() && !cands().length));
const matchAB = b => { const bb = 1 + (gt().length ? 1 : 0), a = (pscore(b)[0] > 0 ? 1 : 0) + (tags(b).some(t => gt().includes(t)) ? 1 : 0); return [a, bb]; };
const why = b => {
  const r = [], [p, k] = pscore(b);
  if (p > 0) {
    if (S.aud === 'near') r.push(fkm(k) + ' from ' + pl());
    else if (S.aud === 'city' || S.aud === 'multi') r.push('In ' + CN(b.c));
    else if (S.aud === 'route') { const rt = RT(S.route); r.push(rt[2].includes(b.c) ? 'On the ' + rt[1] + ' route' : 'At the ' + CN(b.c) + ' end of the route'); }
  }
  tags(b).filter(t => gt().includes(t)).forEach(t => r.push(tagWhy(t, b.c)));
  return r;
};
const defSel = () => {
  const cs = cands();
  if (S.aud === 'near') { let w = cs.filter(b => pscore(b)[1] <= 5).slice(0, 3); if (!w.length && cs[0] && pscore(cs[0])[1] <= 10) w = [cs[0]]; return w.map(b => b.i); }
  if (S.aud === 'city') {
    const c = cs.filter(b => b.c === S.cities[0]); if (c.length <= 4) return c.map(b => b.i);
    const out = [c[0]]; while (out.length < 4) { let best = null, bd = -1; c.forEach(b => { if (out.includes(b)) return; const m = Math.min(...out.map(o => km([o.la, o.lo], [b.la, b.lo]))); if (m > bd) { bd = m; best = b; } }); out.push(best); }
    return out.map(b => b.i);
  }
  if (S.aud === 'multi') return S.cities.flatMap(s => { const c = cs.filter(b => b.c === s); return c.slice(0, c.length >= 5 ? 2 : 1); }).slice(0, 10).map(b => b.i);
  if (S.aud === 'route') { const r = RT(S.route); if (!r) return []; const on = cs.filter(b => r[2].includes(b.c)).slice(0, 4), ends = r[3].map(s => cs.find(b => b.c === s)).filter(Boolean); return on.concat(ends).slice(0, 10).map(b => b.i); }
  return [];
};
const selKey = () => [S.goal, S.aud, S.place && S.place.l, S.cities.join(), S.route].join('|');
const ensureSel = () => {
  if (S.aud === 'multi' && S.cities.length === 1) S.aud = 'city';
  S.check = isCheck();
  if (S.fixedSel) { S.selKey = selKey(); return; }
  const k = selKey(); if (k !== S.selKey) { S.selKey = k; S.sel = S.check ? [] : defSel(); }
};
const startD = () => S.startKey === 'tbd' || !S.start ? add(today(), 14) : pd(S.start);
const nextEid = () => { const t = today(); return P.eids.map(x => ({ n: x[0], bn: x[1], d: pd(x[2]) })).find(x => x.d > t); };
