  const pw = S.check || !top ? 'a place we still need to check' : P.city[top][2] === 3 ? 'Dhaka, where the most brands compete for space' : top === 'chattogram' ? 'Chattogram, the second-largest city' : top === 'narayanganj' ? 'Narayanganj, next to Dhaka' : CN(top) + ', outside the two largest cities';
