  let el = P.pool.filter(x => (x.x.includes('any') || hit(x)) && !S.shown.includes(x.id));
  const fr = el.filter(x => !seen.includes(x.id)); if (fr.length) el = fr; if (!el.length) return null;
  const w = el.map(x => hit(x) ? 2 : 1); let r = Math.random() * w.reduce((a, b) => a + b), i = 0; while ((r -= w[i]) > 0) i++;
